import{_ as s,o as a,c as e,ai as p}from"./chunks/framework.BxxKhjs3.js";const l="/pub-blog/assets/image-20240723105343511.DFSUH-Oe.png",i="/pub-blog/assets/image-20240723110522686.CtBUhJty.png",h=JSON.parse('{"title":"HarmonyOS Next V2 @Event","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 @Event/@Event.md","filePath":"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 @Event/@Event.md","lastUpdated":1730788610000,"__rawMarkdown":"# HarmonyOS Next V2 @Event\\n\\n## 背景\\n\\n在上一节中，我们针对父子组件，讲了关于传递数据的知识。我们了解到\\n\\n1. `@Local` 是管理自己内部的数据的，\\n2. `@Param` 是负责接收父组件的数据的，而且子自己内部不能直接修改\\n\\n按照一个组件最基本的功能，**既能接收外部传入的数据**，**也要向外部传递数据**。那么 `@Even`t 修饰符就是来解决这个问题的了。\\n\\n\\n\\n## 介绍 \\n\\n`@Event` 是 子组件向父组件传递数据的技术，它只能用在 `@ComponentV2`  修改的组件上，其中的思想是\\n\\n1. 完成修改数据的操作，还是放在父组件内部，通过定义一个函数 `func`  来实现\\n2. 在父组件调用子组件的时候，也顺带把这个函数 `func`  传递给子组件\\n3. 子组件在内部 使用 `@Event` 来修饰 该函数，并且在需要的使用直接调用即可\\n\\n\\n\\n## 父组件 \\n\\n1. 定义内部数据 `num` \\n2. 定义修改内部数据`num`的函数 `func`\\n3. 使用子组件时，把`num`和`func`都传递过去\\n\\n```\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local num: number = 100\\n  // 自己定义的函数 负责修改数据， 该函数也要传递给子组件 \\n  func = (unit: number) => {\\n    this.num -= unit\\n  }\\n\\n  build() {\\n    Column() {\\n      Button(\\"父组件 修改\\" + this.num)\\n        .onClick(() => {\\n          this.num++\\n        })\\n      // 使用子组件，并且传递数据 和 传递函数 \\n      Son({ num: this.num, func: this.func })\\n        .padding(10)\\n    }\\n    .width(\\"100%\\")\\n\\n  }\\n}\\n```\\n\\n## 子组件\\n\\n1. 使用 `@Param` 接收父组件传递的 `num`\\n2. 使用`@Event`  接收父组件传递的函数 `func`\\n3. 定义点击事件的处理函数 `onfunc`，内部直接调用父组件传递过来的函数\\n\\n```\\n@ComponentV2\\nstruct Son {\\n  @Param num: number = 0\\n  @Event func: (num: number) => void = () => {\\n  }\\n  onfunc = () => {\\n    this.func(5)\\n  }\\n\\n  build() {\\n\\n    Column() {\\n      Button(`子组件 ${this.num}`)\\n\\n      Button(\\"子组件修改父组件中的状态\\")\\n        .onClick(this.onfunc)\\n    }\\n    .border({\\n      width: 1,\\n      style: BorderStyle.Dashed\\n    })\\n  }\\n}\\n```\\n\\n## 流程\\n\\n![image-20240723105343511](readme.assets/image-20240723105343511.png)\\n\\n## @Once\\n\\n`@Once` 和 `@Param`作用类似，都可以表示接收父组件传递过来的数据，但是也存在区别\\n\\n1. `@Once` 只会接收第一次父组件传递过来的数据，后续父组件的数据修改，不会同步到 `@Once`修改的变量上\\n2. `@Once` 需要和 `@Param` 一起搭配使用，因为 `@Param` 修饰的是父组件传递给子组件的变量，该变量不能直接被修改。所以`@Once`修饰的变量，也不能在子组件内部直接修改。\\n\\n\\n\\n```\\n@ComponentV2\\nstruct Son {\\n  @Once @Param num: number = 0\\n\\n  build() {\\n    Column() {\\n      Button(`子组件 ${this.num}`)\\n        .onClick(() => {\\n          this.num++ // 修改无效 \\n        })\\n    }\\n    .border({\\n      width: 1,\\n      style: BorderStyle.Dashed\\n    })\\n  }\\n}\\n\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local num: number = 100\\n\\n  build() {\\n    Column() {\\n\\n      Son({ num: this.num })\\n        .padding(10)\\n    }\\n    .width(\\"100%\\")\\n\\n  }\\n}\\n```\\n\\n![image-20240723110522686](readme.assets/image-20240723110522686.png)\\n\\n\\n\\n## 总结\\n\\n1. `@Param` 表示父组件传递给子组件的数据，当父组件修改了，子组件会跟随响应，同时子组件内部不能直接修改 `@Param`修饰的变量\\n2. `@Event`  表示子组件想要修改父组件数据的一种技术，它用来修改函数，该函数是由父组件定义和传递给子组件的\\n3. `@Once` 必须和 `@Param` 搭配使用，表示父组件传递过来的数据，只会第一次生效。\\n\\n\\n\\n"}'),c={name:"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 @Event/@Event.md"};function r(t,n,o,u,m,b){return a(),e("div",null,[...n[0]||(n[0]=[p("",23)])])}const v=s(c,[["render",r]]);export{h as __pageData,v as default};
